+/* ---------------- ramp mesh (ribbon with thickness) + LED edges ---------------- */
+(function buildRamp(){
+  const pts=PROF.filter((_,i)=>i%2===0||i===PROF.length-1);
+  const W=RAMP_HALF_W, TH=0.38;
+  const pos=[],nor=[],uv=[],idx=[];
+  // top surface vertices (0..n-1 pairs), then bottom surface pairs
+  pts.forEach((p,i)=>{
+    pos.push(p.x,p.y,-W, p.x,p.y,W);
+    nor.push(p.nx,p.ny,0, p.nx,p.ny,0);
+    uv.push(0,p.s/3.4, 1,p.s/3.4);
+  });
+  const nTop=pts.length*2;
+  pts.forEach((p,i)=>{
+    pos.push(p.x-p.nx*TH,p.y-p.ny*TH,-W, p.x-p.nx*TH,p.y-p.ny*TH,W);
+    nor.push(-p.nx,-p.ny,0, -p.nx,-p.ny,0);
+    uv.push(0,p.s/3.4, 1,p.s/3.4);
+  });
+  for(let i=0;i<pts.length-1;i++){
+    const a=i*2,b=i*2+1,c=i*2+2,d=i*2+3;
+    idx.push(a,c,b, b,c,d);                                  // top
+    const a2=nTop+a,b2=nTop+b,c2=nTop+c,d2=nTop+d;
+    idx.push(a2,b2,c2, b2,d2,c2);                            // bottom
+    idx.push(a,a2,c, c,a2,c2);                               // left side
+    idx.push(b,d,b2, d,d2,b2);                               // right side
+  }
+  // lip end cap
+  const li=(pts.length-1)*2;
+  idx.push(li,li+1,nTop+li, li+1,nTop+li+1,nTop+li);
+  const geo=new THREE.BufferGeometry();
+  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
+  geo.setAttribute('normal',new THREE.Float32BufferAttribute(nor,3));
+  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
+  geo.setIndex(idx);
+  const rampTop=new THREE.Mesh(geo,M.concrete);
+  rampTop.castShadow=true; rampTop.receiveShadow=true; scene.add(rampTop);
+  // thin side skirts slightly wider, dark, under the edge lights
+  for(const sz of [-1,1]){
+    const curve=new THREE.CatmullRomCurve3(pts.filter((_,i)=>i%4===0).map(p=>new THREE.Vector3(p.x+p.nx*0.035,p.y+p.ny*0.035,sz*(W-0.02))));
+    const tube=new THREE.Mesh(new THREE.TubeGeometry(curve,220,0.035,6,false),M.ledRed);
+    tube.castShadow=false; scene.add(tube);
+    const curve2=new THREE.CatmullRomCurve3(pts.filter((_,i)=>i%4===0).map(p=>new THREE.Vector3(p.x-p.nx*0.10,p.y-p.ny*0.10,sz*(W+0.02))));
+    const rail=new THREE.Mesh(new THREE.TubeGeometry(curve2,160,0.05,6,false),M.steelDark);
+    rail.castShadow=true; scene.add(rail);
+  }
+  // start line on flat
+  const sl=box(0.18,0.012,W*1.8,new THREE.MeshStandardMaterial({color:0xdddddd,roughness:0.6}),-9.5,0.008,0);
+  sl.castShadow=false; scene.add(sl);
+})();
