+/* steel truss behind the running surface */
+(function buildTruss(){
+  const g=new THREE.Group(); scene.add(g);
+  const backX=LIP.x+3.1, topY=LIP.y+0.8, H=topY;
+  const zs=[-2.0,2.0];
+  // two rear vertical towers with lattice bracing
+  for(const z of zs){
+    beam(new THREE.Vector3(backX,0,z),new THREE.Vector3(backX,H,z),0.14,M.steel,g);
+    beam(new THREE.Vector3(backX-1.5,0,z),new THREE.Vector3(backX-0.4,H,z),0.09,M.steel,g);
+    const bays=7;
+    for(let i=0;i<bays;i++){
+      const y0=i/bays*H, y1=(i+1)/bays*H;
+      const x0a=backX-1.5+ (1.1)*(y0/H), x1a=backX-1.5+(1.1)*(y1/H);
+      beam(new THREE.Vector3(x0a,y0,z),new THREE.Vector3(backX,y1,z),0.05,M.steelDark,g);
+      beam(new THREE.Vector3(backX,y0,z),new THREE.Vector3(x1a,y1,z),0.05,M.steelDark,g);
+      beam(new THREE.Vector3(backX,y0,z),new THREE.Vector3(x0a,y0,z),0.05,M.steelDark,g);
+    }
+  }
+  // cross members between towers + X brace on back face
+  for(let i=0;i<=7;i++){
