+  }
+  beam(new THREE.Vector3(backX,1,-2.0),new THREE.Vector3(backX,H*0.55,2.0),0.05,M.steelDark,g);
+  beam(new THREE.Vector3(backX,1,2.0),new THREE.Vector3(backX,H*0.55,-2.0),0.05,M.steelDark,g);
+  beam(new THREE.Vector3(backX,H*0.5,-2.0),new THREE.Vector3(backX,H-1,2.0),0.05,M.steelDark,g);
+  beam(new THREE.Vector3(backX,H*0.5,2.0),new THREE.Vector3(backX,H-1,-2.0),0.05,M.steelDark,g);
+  // struts from surface back to towers, following the hook
+  const step=38;
+  for(let i=60;i<PROF.length;i+=step){
+    const p=PROF[i];
+    const bx=p.x-p.nx*0.4, by=p.y-p.ny*0.4;
+    for(const z of zs){
+      beam(new THREE.Vector3(bx,by,z*0.92),new THREE.Vector3(backX,clamp(by,0.4,H-0.3),z),0.06,M.steel,g);
+    }
+    beam(new THREE.Vector3(bx,by,-1.85),new THREE.Vector3(bx,by,1.85),0.055,M.steelDark,g);
+    // diagonal from surface point down-back to tower base area
+    if(p.y>4) for(const z of zs) beam(new THREE.Vector3(bx,by,z*0.92),new THREE.Vector3(backX,clamp(by-3.2,0.3,H),z),0.045,M.steelDark,g);
+  }
+  // top crossbeam extending past lip (visible in aerial frame 23)
+  beam(new THREE.Vector3(LIP.x-4.6,LIP.y+0.85,0),new THREE.Vector3(backX+0.4,LIP.y+0.85,0),0.09,M.steel,g);
+  for(const z of zs) beam(new THREE.Vector3(backX,H,z),new THREE.Vector3(LIP.x-1.2,LIP.y+0.85,0),0.05,M.steelDark,g);
+  // base frame + feet
+  beam(new THREE.Vector3(-5,0.18,-2.3),new THREE.Vector3(backX+0.6,0.18,-2.3),0.09,M.steelDark,g);
+  beam(new THREE.Vector3(-5,0.18,2.3),new THREE.Vector3(backX+0.6,0.18,2.3),0.09,M.steelDark,g);
+  beam(new THREE.Vector3(backX,0,0),new THREE.Vector3(backX-6.5,0.1,-3.4),0.07,M.steelDark,g);
+  beam(new THREE.Vector3(backX,0,0),new THREE.Vector3(backX-6.5,0.1,3.4),0.07,M.steelDark,g);
+  // small red marker lights on tower
+  for(let i=1;i<=5;i++){ const m=box(0.12,0.12,0.12,M.ledRed,backX+0.16,i*H/5.5,0); m.castShadow=false; g.add(m); }
+})();

